{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 3,
      "text_ar": "في السنة الثلاثين بعد خراب المدينة، كنت أنا سالاتئيل، المسمى أيضاً عزرا، في بابل، وكنت مضطجعاً على فراشي، وصعدت أفكاري إلى قلبي،",
      "verse": 1
    },
    {
      "chapter": 3,
      "text_ar": "لأني رأيت خراب صهيون وثروة الساكنين في بابل.",
      "verse": 2
    },
    {
      "chapter": 3,
      "text_ar": "فاضطربت روحي جداً، حتى ابتدأت أتكلم بكلام مملوء خوفاً إلى العلي، وقلت:",
      "verse": 3
    },
    {
      "chapter": 3,
      "text_ar": "«أيها السيد الرب، ألم تتكلم في البدء حين صنعت الأرض وحدك بنفسك وأمرت التراب،",
      "verse": 4
    },
    {
      "chapter": 3,
      "text_ar": "فأعطاك آدم، جسداً بلا نفس؟ ومع ذلك كان صنعة يديك، ونفخت فيه نسمة الحياة، فعاش أمامك».",
      "verse": 5
    }
  ]
}
